<script setup lang="ts">const db=useSupabaseClient();const route=useRoute();const email=ref('');const password=ref('');const busy=ref(false);const error=ref('');async function submit(){busy.value=true;error.value='';try{const result=await db.auth.signInWithPassword({email:email.value,password:password.value});if(result.error)throw result.error;const {data:admin}=await db.rpc('is_platform_admin');const {data:{user}}=await db.auth.getUser();const {data:memberships}=user?await db.from('school_memberships').select('role').eq('user_id',user.id):{data:[]};const redirect=typeof route.query.redirect==='string'&&route.query.redirect.startsWith('/')&&!route.query.redirect.startsWith('//')&&!route.query.redirect.includes('\\')?route.query.redirect:'';await navigateTo(redirect||(admin?'/dashboard':(memberships||[]).some((m:any)=>['teacher','school_admin'].includes(m.role))?'/dashboard':'/student'))}catch(e:any){error.value=e?.message||'Sign in failed'}finally{busy.value=false}}</script><template><div class="grid min-h-screen place-items-center bg-slate-50 px-4"><form class="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-8 shadow-sm" @submit.prevent="submit"><NuxtLink to="/" aria-label="School Sports Tracker home" class="mx-auto flex justify-center"><img src="/logo.png" alt="School Sports Tracker" class="h-40 w-full max-w-[260px] object-contain" /></NuxtLink><h1 class="mt-5 text-3xl font-bold">Welcome back</h1><p class="mt-2 text-sm text-slate-500">Sign in to manage school sport.</p><label class="mt-8 block text-sm font-semibold">Email<input v-model="email" required type="email" autocomplete="email" class="mt-2 w-full rounded-xl border border-slate-300 p-3"/></label><label class="mt-5 block text-sm font-semibold">Password<input v-model="password" required type="password" autocomplete="current-password" class="mt-2 w-full rounded-xl border border-slate-300 p-3"/></label><p v-if="error" role="alert" class="mt-4 text-sm text-red-600">{{error}}</p><button :disabled="busy" class="mt-7 w-full rounded-xl bg-blue-600 p-3 font-semibold text-white disabled:opacity-50">{{busy?'Signing in…':'Sign in'}}</button></form></div></template>